                unplaced += 1
                continue

            node = 1
            while node < size:
                left = node << 1
                if tree[left] >= fruit:
                    node = left
                else:
                    node = left | 1

            tree[node] = 0

            while node > 1:
                node >>= 1
                tree[node] = max(tree[node << 1], tree[(node << 1) | 1])

        return unplaced
