    def maxSum(self, nums: List[int], k: int, m: int) -> int:
        n = len(nums)
        prefix = [0] * (n + 1)
        for i, x in enumerate(nums, 1):
            prefix[i] = prefix[i - 1] + x

        NEG = -10**18

        # prev[i] = maximum sum using the current number of subarrays
        # in nums[:i]. Initially, 0 subarrays have sum 0.
        prev = [0] * (n + 1)

        for _ in range(k):
            cur = [NEG] * (n + 1)
            best = NEG

            for i in range(1, n + 1):
                # A subarray ending at i can start at any t <= i - m.
                # Its contribution is prev[t] + prefix[i] - prefix[t].
                if i >= m:
                    pv = prev[i - m]
                    if pv != NEG:
                        val = pv - prefix[i - m]
                        if val > best:
                            best = val

                if best != NEG:
                    val = best + prefix[i]
                    cur[i] = val if val > cur[i - 1] else cur[i - 1]
                else:
                    cur[i] = cur[i - 1]

            prev = cur

