    def separateSquares(self, squares: List[List[int]]) -> float:
        # x-coordinates do not affect the area above/below a horizontal line.
        # For each square, only its vertical interval [y, y + l] and weight l matter.
        events = []
        total_area = 0

        for _, y, l in squares:
            total_area += l * l
            events.append((y, l))          # square starts: slope increases by l
            events.append((y + l, -l))     # square ends: slope decreases by l

        events.sort()

        # We solve: 2 * area_below(h) = total_area
        target = total_area

        area2 = 0          # 2 * area_below at the current event y
        slope = 0          # derivative of area_below, i.e. sum of active l
        i = 0
        m = len(events)
        prev_y = events[0][0]

        while i < m:
            y = events[i][0]

            # Advance area from prev_y to y using the current slope.
            if y > prev_y:
                area2 += 2 * slope * (y - prev_y)

            # If the half-area point is exactly at this event, this is the minimum y.
            if target <= area2:
                return float(y)

            # Apply all events at this y to get the slope for the next segment.
            while i < m and events[i][0] == y:
                slope += events[i][1]
                i += 1

            prev_y = y

            # Check the open segment [y, next_y).
            if i < m:
                next_y = events[i][0]
                if slope > 0:
                    end_area2 = area2 + 2 * slope * (next_y - y)
                    if target <= end_area2:
                        if target == end_area2:
                            return float(next_y)
                        return float(y + (target - area2) / (2.0 * slope))

        return float(prev_y)
