        starts = sorted(set(first[c] for c in chars))
        ends = sorted(set(last[c] for c in chars))

        intervals = []

        for l in starts:
            for r in ends:
                if r < l:
                    continue
                if l == 0 and r == n - 1:
                    continue

                ok = True
                for c in chars:
                    p = positions[c]
                    idx = bisect_left(p, l)
                    if idx < len(p) and p[idx] <= r:
                        if first[c] < l or last[c] > r:
