def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    S = data[2]
    T = data[3]

    c = T[-1] - 48
    c_ascii = c + 48

    # Counts of optional digits (all digits of T except the last one).
    counts = [0] * 10
    for b in T:
        counts[b - 48] += 1
    counts[c] -= 1

    # First pass:
    # Compute the optional-only greedy result on the fly.
    # Find the optimal position p for the mandatory digit c:
    # - first position where c > optional-only digit, if any
    # - otherwise first position where c == optional-only digit, if any
    # - otherwise the last position
    opt = counts[:]
    maxd = 9
    while maxd > 0 and opt[maxd] == 0:
        maxd -= 1

    p = -1
    eq = -1

    for i, b in enumerate(S):
        s = b - 48
        if maxd > s:
            a = maxd + 48
            opt[maxd] -= 1
            if opt[maxd] == 0:
                while maxd > 0 and opt[maxd] == 0:
                    maxd -= 1
        else:
            a = b

        if c_ascii > a:
            p = i
            break
        if c_ascii == a and eq == -1:
            eq = i

    if p == -1:
        p = eq if eq != -1 else N - 1

    # Second pass:
    # Construct the final string, forcing the mandatory digit at position p.
    opt = counts[:]
    maxd = 9
    while maxd > 0 and opt[maxd] == 0:
        maxd -= 1

    ans = bytearray(N)

    for i in range(p):
        b = S[i]
        s = b - 48
        if maxd > s:
            ans[i] = maxd + 48
            opt[maxd] -= 1
            if opt[maxd] == 0:
                while maxd > 0 and opt[maxd] == 0:
                    maxd -= 1
        else:
            ans[i] = b

    ans[p] = c_ascii

    for i in range(p + 1, N):
        b = S[i]
        s = b - 48
        if maxd > s:
            ans[i] = maxd + 48
            opt[maxd] -= 1
            if opt[maxd] == 0:
                while maxd > 0 and opt[maxd] == 0:
                    maxd -= 1
        else:
            ans[i] = b

    sys.stdout.buffer.write(ans)
    sys.stdout.buffer.write(b"\n")


