from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        arr = nums
        K = k
        BLOCK = 32

        def brute(l, r, a=arr, K=K):
            ans = 0
            for i in range(l, r + 1):
                pmax = 0
                cost = 0
                for j in range(i, r + 1):
                    v = a[j]
                    if v > pmax:
                        pmax = v
                    else:
                        cost += pmax - v
                    if cost <= K:
                        ans += 1
                    else:
                        break
            return ans

        def cross(l, mid, r, a=arr, K=K):
            mR = r - mid

            prefA = [0] * (mR + 1)
            prefP = [0] * (mR + 1)
            P = [0] * mR

            pmax = 0
            sa = 0
            sp = 0
            for t in range(1, mR + 1):
                v = a[mid + t]
                if v > pmax:
                    pmax = v
                sa += v
                sp += pmax
                prefA[t] = sa
                prefP[t] = sp
                P[t - 1] = pmax

            # Stack stores prefix-max segments for the current left part,
            # in reverse order (front segment at the end).
            sv = [a[mid]]
            sl = [1]

            cost = 0
            M = a[mid]
            p = 1
            j = mR
            ans = 0

            while p <= mR and P[p - 1] <= M:
                p += 1

            while j > 0:
                if j < p:
                    extra = M * j - prefA[j]
                else:
                    extra = M * (p - 1) + (prefP[j] - prefP[p - 1]) - prefA[j]
                if cost + extra <= K:
                    break
                j -= 1

            if j > 0:
                ans += j
            if j == 0:
                return ans

            for i in range(mid - 1, l - 1, -1):
                x = a[i]
                popped_len = 0
                popped_cost = 0

                while sv and sv[-1] <= x:
                    v = sv.pop()
                    ln = sl.pop()
                    popped_len += ln
                    popped_cost += v * ln

                cost += x * popped_len - popped_cost
                sv.append(x)
                sl.append(1 + popped_len)

                if x > M:
                    M = x

                if cost > K:
                    break

                while p <= mR and P[p - 1] <= M:
                    p += 1

                while j > 0:
                    if j < p:
                        extra = M * j - prefA[j]
                    else:
                        extra = M * (p - 1) + (prefP[j] - prefP[p - 1]) - prefA[j]
                    if cost + extra <= K:
                        break
                    j -= 1

                if j > 0:
                    ans += j
                else:
                    break

            return ans

        def solve(l, r):
            if r - l + 1 <= BLOCK:
                return brute(l, r)
            mid = (l + r) >> 1
            return solve(l, mid) + solve(mid + 1, r) + cross(l, mid, r)

        return solve(0, n - 1)
